def esc(s): return s.replace('\\','\\\\').replace('(','\\(').replace(')','\\)')
objects = []
objects.append('<< /Type /Catalog /Pages 2 0 R >>')
objects.append('<< /Type /Pages /Kids [' + ' '.join(f'{3+i*3} 0 R' for i in range(len(pages))) + f'] /Count {len(pages)} >>')
for i, lines in enumerate(pages):
    content=['BT','/F1 18 Tf','72 750 Td',f'({esc(lines[0])}) Tj','/F1 10 Tf']
    for line in lines[1:]: content += ['0 -22 Td',f'({esc(line)}) Tj']
    content.append('ET'); stream='\n'.join(content)
    objects.append(f'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 {4+i*3} 0 R >> >> /Contents {5+i*3} 0 R >>')
    objects.append('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    objects.append(f'<< /Length {len(stream.encode("latin-1"))} >>\nstream\n{stream}\nendstream')
out = '%PDF-1.4\n'; offsets=[0]
for n,obj in enumerate(objects,1): offsets.append(len(out.encode('latin-1'))); out += f'{n} 0 obj\n{obj}\nendobj\n'
xref=len(out.encode('latin-1')); out += f'xref\n0 {len(objects)+1}\n0000000000 65535 f \n' + ''.join(f'{o:010d} 00000 n \n' for o in offsets[1:]) + f'trailer\n<< /Size {len(objects)+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n'
Path('results/submission_report.pdf').write_bytes(out.encode('latin-1'))
